export const blogCategories = ['All', 'Treatments', 'Skin routines', 'Local guides'] as const;

export const getBlogPost = (slug: string) => blogPosts.find((post) => post.slug === slug);

export const getRelatedPosts = (current: BlogPost, count = 3) => {
  const sameCategory = blogPosts.filter((item) => item.slug !== current.slug && item.category === current.category);
  const others = blogPosts.filter((item) => item.slug !== current.slug && item.category !== current.category);
  return [...sameCategory, ...others].slice(0, count);
};
